let db, current, busy=false;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=()=>new Date().toISOString();
const localTime=s=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Fortaleza',dateStyle:'short',timeStyle:'medium'}).format(new Date(s));
const dateToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let openingDB=null;
function deadline(p,ms,label){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error(label)),ms);Promise.resolve(p).then(v=>{clearTimeout(timer);resolve(v);},e=>{clearTimeout(timer);reject(e);});});}
function openLocalDB(){if(db)return Promise.resolve(db);if(openingDB)return openingDB;openingDB=deadline(new Promise((resolve,reject)=>{const req=indexedDB.open('ppl-inspections',2);req.onupgradeneeded=()=>{for(const name of ['records','pdfs','management'])if(!req.result.objectStoreNames.contains(name))req.result.createObjectStore(name,{keyPath:'key'});};req.onblocked=()=>message('Feche outras abas antigas do aplicativo para concluir a atualização do armazenamento.',true);req.onerror=()=>reject(req.error);req.onsuccess=()=>{const connection=req.result;db=connection;connection.onclose=()=>{if(db===connection)db=null;};connection.onversionchange=()=>{connection.close();if(db===connection)db=null;};resolve(connection);};}),15000,'Armazenamento ocupado. Feche outras abas do aplicativo e tente novamente.').finally(()=>{openingDB=null;});return openingDB;}
async function localOperation(store,mode,action){for(let attempt=0;attempt<2;attempt++){const connection=await openLocalDB();try{return await deadline(new Promise((resolve,reject)=>{let tx;try{tx=connection.transaction(store,mode);}catch(e){reject(e);return;}let result;const timer=setTimeout(()=>{tx.pplError=Error('O armazenamento não respondeu. Tente novamente.');try{tx.abort();}catch{}reject(tx.pplError);},18000);tx.oncomplete=()=>{clearTimeout(timer);resolve(typeof result==='function'?result():result?.result);};tx.onerror=()=>{clearTimeout(timer);reject(tx.error||Error('Falha no armazenamento local.'));};tx.onabort=()=>{clearTimeout(timer);reject(tx.pplError||tx.error||Error('Gravação local interrompida.'));};try{result=action(tx.objectStore(store),tx);}catch(e){tx.pplError=e;tx.abort();}}),20000,'O armazenamento não respondeu. Os dados em preenchimento foram mantidos nesta tela; tente novamente.');}catch(e){if(attempt===0&&['InvalidStateError','UnknownError'].includes(e?.name)){if(db===connection)db=null;connection.close();continue;}throw e;}}}
function transaction(store,mode,action){return localOperation(store,mode,action);}
const transientRecords=new Map();
function recordContent(x){const c=structuredClone(x);delete c.pdfStatus;delete c.syncStatus;return JSON.stringify(c);}
function recoveryRows(){const rows=[];try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith('ppl-recovery:')){try{const r=JSON.parse(localStorage.getItem(k));if(validImport(r))rows.push(r);}catch{}}}}catch{}return rows;}
function recoveryWrite(r){try{const k='ppl-recovery:'+r.key,old=JSON.parse(localStorage.getItem(k)||'null');if(old?.status==='recorded'&&recordContent(old)!==recordContent(r))throw Error('Registro já preservado. Crie uma correção.');localStorage.setItem(k,JSON.stringify(r));return true;}catch(e){if(e.message==='Registro já preservado. Crie uma correção.')throw e;return false;}}
const put=async r=>{const snapshot=structuredClone(r);const journalOld=recoveryRows().find(x=>x.key===snapshot.key);if(journalOld?.status==='recorded'&&recordContent(journalOld)!==recordContent(snapshot))throw Error('Registro já preservado. Crie uma correção.');try{await localOperation('records','readwrite',(s,tx)=>{const read=s.get(snapshot.key);read.onsuccess=()=>{const old=read.result;if(old?.status==='recorded'&&recordContent(old)!==recordContent(snapshot)){tx.pplError=Error('Registro já preservado em outra aba. Reabra-o e crie uma correção.');tx.abort();return;}s.put(snapshot);};});recoveryWrite(snapshot);}catch(e){if(/Registro já preservado/.test(e.message)||!recoveryWrite(snapshot))throw e;message('Registro preservado pela cópia de recuperação. Armazenamento principal indisponível; mantenha esta página aberta até confirmar o envio.',true);}};
const all=async()=>{let rows;try{rows=await transaction('records','readonly',s=>s.getAll());}catch(e){rows=recoveryRows();if(!rows.length&&!transientRecords.size)throw e;}const merged=new Map([...transientRecords.values(),...rows].map(r=>[r.key,r]));for(const r of recoveryRows()){const old=merged.get(r.key);if(!old||(old.status!=='recorded'&&(r.status==='recorded'||r.updatedAt>old.updatedAt)))merged.set(r.key,r);}return [...merged.values()];};
const getRecord=async k=>(await all()).find(r=>r.key===k);
const key=r=>r.id+':'+r.revision;
function message(s,error=false){$('#message').textContent=s;$('#message').classList.toggle('error',error);}
function fresh(model=MODEL){return {key:'',id:recordUUID(),revision:1,model:JSON.parse(JSON.stringify(model)),createdAt:stamp(),updatedAt:stamp(),status:'draft',syncStatus:'local-only',pdfStatus:'pending',fields:{type:model.types.length===1?model.types[0]:'',date:dateToday(),belt:'',lanyard:'',inspector:'',employee:'',notes:'',reason:'',beltState:'Sem baixa informada',lanyardState:'Sem baixa informada',dispositionNotes:'',unit:'',team:'',lanyardDamage:''},signature:null,workerPhoto:null,answers:model.items.map(i=>({itemId:i.id,value:'',notes:'',photos:[]}))};}
async function newRecord(){const chosen=EQUIPMENT_CATALOG.find(e=>e.id===selectedEquipment);if(!chosen||!getModel(chosen.modelId)){message('Selecione um equipamento com checklist disponível.',true);return;}current=fresh(getModel(chosen.modelId));for(const f of current.model.identifiers||[])current.fields[f.name]='';current.equipmentType={id:chosen.id,name:chosen.name};current.key=key(current);await put(current);await list();render();$('#workspace').scrollIntoView({behavior:'smooth',block:'start'});}
async function list(){const records=await all();$('#overview').innerHTML=`<div class="metric"><b>${new Set(records.map(r=>r.id)).size}</b><span>Inspeções locais</span></div><div class="metric"><b>${records.filter(r=>r.status==='draft').length}</b><span>Rascunhos</span></div><div class="metric"><b>${records.filter(r=>r.status==='recorded').length}</b><span>Revisões registradas</span></div>`;records.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));$('#records').innerHTML=records.length?records.map(r=>`<button class="record" data-key="${esc(r.key)}"><strong>${esc(r.fields.belt||'Sem identificação')} · r${r.revision}</strong><small>${esc(equipmentLabel(r))}</small>${r.status==='draft'?'Rascunho':'Registrado · avaliação pendente'}<small>${localTime(r.updatedAt)}<br>${esc(r.id.slice(0,8))} · PDF ${r.pdfStatus==='ready'?'pronto':'pendente'}</small></button>`).join(''):'<p class="muted">Nenhuma inspeção ainda.</p>';$('#records').querySelectorAll('button').forEach(b=>b.onclick=async()=>{if(busy)return;current=await getRecord(b.dataset.key);render();message('');});}
function field(name,label,type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(current.fields[name])}" ${name==='inspector'?'autocomplete="name"':'autocomplete="off"'} ${type==='date'?'max="'+dateToday()+'"':''} ${required?'required':''}>${type==='date'?'<button type="button" class="calendar-button" data-picker="'+name+'">Selecionar no calendário</button>':''}</label>`;}
function disposition(name,label){return '<label>'+label+'<select name="'+name+'">'+['Sem baixa informada',...(name==='beltState'?['Em uso']:[]),'Inativado','Entregue','Descartado'].map(v=>'<option '+(current.fields[name]===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label>';}
function render(){if(current)rememberInspection(current);if(typeof showChecklist==='function')showChecklist();if(!current){renderEquipmentHome();return;}const r=current,draft=r.status==='draft',component=r.model.equipmentMode==='component',generic=r.model.equipmentMode==='generic';$('#workspace').innerHTML=`<form id="form"><div class="panel"><h2>${esc(equipmentLabel(r))}</h2><p class="muted">${esc(r.model.title)}</p><div class="fill-progress" aria-live="polite"><div><strong id="progress-count">${r.answers.filter(a=>a.value).length} de ${r.answers.length} itens respondidos</strong><span>${draft?'Preenchimento':'Registro preservado'}</span></div><progress id="progress-bar" max="${r.answers.length}" value="${r.answers.filter(a=>a.value).length}"></progress></div><p class="status">ID ${esc(r.id)} · revisão ${r.revision}<br>Modelo ${esc(r.model.version)} · ${draft?'Rascunho':'Registro preservado'}<br>Horários do dispositivo exibidos em America/Fortaleza</p><fieldset ${draft?'':'disabled'} style="border:0;padding:0;margin:0"><div class="grid"><div class="type-selection"><span class="field-label">Tipo de inspeção</span><div class="type-cards">${r.model.types.map(t=>`<label class="tap-choice"><input type="radio" name="type" value="${esc(t)}" ${t===r.fields.type?'checked':''} required><span>${esc(t)}</span></label>`).join('')}</div></div>${field('date','Data da inspeção','date')}${field('belt',generic?r.model.identificationLabel:'Número(s) de série do cinturão / TAG')}${(r.model.identifiers||[]).map(f=>field(f.name,f.label+' (se houver)','text',false)).join('')}${component?'<div class="component-info"><strong>Talabarte integrante do conjunto</strong><p>Sem TAG própria. Verifique suas condições nos itens abaixo.</p></div>':generic?'':field('lanyard','Identificação histórica do talabarte')}${field('inspector','Nome do inspetor / usuário')}${field('employee','Matrícula')}<label>Unidade<input name="unit" value="${esc(r.fields.unit||'')}"></label><label>Equipe<input name="team" value="${esc(r.fields.team||'')}"></label>${disposition('beltState',generic?'Situação do equipamento':'Situação do cinturão')}${component||generic?'':disposition('lanyardState','Situação histórica do talabarte')}</div>${component?`<label>Avarias adicionais do talabarte (opcional)<textarea name="lanyardDamage" placeholder="Descreva algum defeito, rasgo ou avaria adicional, se houver.">${esc(r.fields.lanyardDamage||'')}</textarea><small>Se houver avaria, marque Não Conforme no item de verificação correspondente.</small></label>`:''}<label>Observação da situação / baixa<textarea name="dispositionNotes">${esc(r.fields.dispositionNotes)}</textarea></label>${r.revision>1?field('reason','Motivo da correção'):''}</fieldset>${generic?`<details class="source-reference"><summary>Referência do checklist</summary><p>${esc(r.model.source.form)} · Aba: ${esc(r.model.source.sheet.trim())}</p><p>Classifique a condição observada como Conforme, Não Conforme ou Não Aplicável. O responsável pela inspeção determina o resultado.</p>${r.model.source.guidance.map(t=>`<p>${esc(t).replace(/\n/g,'<br>')}</p>`).join('')}</details>`:''}</div>${r.model.items.map((item,n)=>{const a=r.answers[n];return `<article class="panel item"><h3>${n+1}. ${esc(item.category)}</h3><small>${generic?`Item ${esc(item.sourceNumber)} do formulário de origem`:`Vínculo proposto: ${esc(item.target)} · validar com responsável técnico`}</small><p>${esc(item.text)}</p><fieldset ${draft?'':'disabled'} style="border:0;padding:0"><fieldset class="answer-group"><legend>Selecione uma resposta</legend><div class="answer-cards">${ANSWERS.map((v,j)=>`<label class="tap-choice answer-${j}"><input type="radio" name="answer-${n}" value="${v}" ${a.value===v?'checked':''} required><span>${v}</span></label>`).join('')}</div></fieldset><details class="item-notes" id="notes-${n}" ${a.notes||a.value==='Não Aplicável'||a.value==='Não Conforme'?'open':''}><summary>Observação / justificativa <span class="note-required">${a.value==='Não Aplicável'?'(obrigatória)':'(opcional)'}</span></summary><label>Descreva o que foi observado<textarea name="note-${n}" ${a.value==='Não Aplicável'?'required':''}>${esc(a.notes)}</textarea></label></details>${draft?`<label>Fotos da inspeção (até 3 por item)<input type="file" data-photo="${n}" accept="image/*" multiple></label>`:''}</fieldset><div class="photos">${a.photos.map((p,j)=>`<div class="photo"><img class="thumb" src="${p.data}" alt="Evidência do item ${n+1}">${draft?`<br><button type="button" data-remove="${n}:${j}">Remover</button>`:''}</div>`).join('')}</div></article>`;}).join('')}<div class="panel"><label>Observações gerais<textarea name="notes" ${draft?'':'disabled'}>${esc(r.fields.notes)}</textarea></label><p class="muted">${draft?'Rascunho salvo automaticamente ao alterar os campos.':'Registro fechado para edição. Correções preservam a revisão anterior.'}</p><p><strong>${r.answers.some(a=>a.value==='Não Conforme')?'Há Não Conforme. Tratamento e avaliação técnica pendentes.':'Avaliação técnica pendente.'}</strong> Nenhum registro libera equipamento.</p><div class="responsibility-grid"><div class="signature"><h3>Assinatura do responsável</h3><p class="muted">Assinatura eletrônica desenhada neste piloto. Não é assinatura com certificado digital.</p>${draft?'<canvas id="signature" width="900" height="240" aria-label="Área para desenhar assinatura com dedo ou mouse"></canvas><button type="button" id="clear-signature">Limpar assinatura</button>':(r.signature?'<img class="signature-image" src="'+r.signature.data+'" alt="Assinatura declarada do responsável">':'<p>Sem assinatura</p>')}</div><div class="worker-photo"><h3>Registro fotográfico do colaborador</h3><p class="muted">Obrigatório para registrar a inspeção. Tire ou selecione uma foto do responsável.</p>${r.workerPhoto?`<img class="worker-photo-image" src="${r.workerPhoto.data}" alt="Registro fotográfico declarado do colaborador">`:draft?'<div class="worker-photo-placeholder">Foto do colaborador ainda não adicionada</div>':'<p class="muted">Foto não exigida no registro original desta versão.</p>'}${draft?`<label class="worker-photo-upload">${r.workerPhoto?'Substituir foto':'Tirar / selecionar foto'}<input id="worker-photo-input" type="file" accept="image/*" capture="user" ${r.workerPhoto?'':'required'}></label>${r.workerPhoto?'<button id="remove-worker-photo" type="button">Remover foto</button>':''}`:''}</div></div><div class="actions">${draft?'<button type="submit" class="primary">Salvar inspeção e preparar PDF</button>':'<button type="button" id="pdf" class="primary">Exportar relatório PDF</button><button type="button" id="correct">Criar correção</button>'}<div id="pdf-output" class="pdf-output" role="status"></div></div><details class="backup-record"><summary>Backup do registro (JSON)</summary><p class="muted">Use o JSON somente para restaurar os dados no aplicativo. O relatório para leitura é o PDF.</p><button type="button" id="json">Baixar backup JSON</button></details></div></form>`;
if(draft){setupSignature();$('#worker-photo-input').onchange=attachWorkerPhoto;if($('#remove-worker-photo'))$('#remove-worker-photo').onclick=async()=>{if(busy)return;current.workerPhoto=null;await put(current);render();};$('#form').querySelectorAll('[data-picker]').forEach(b=>b.onclick=()=>{const input=$(`[name="${b.dataset.picker}"]`);try{input.showPicker();}catch{input.focus();}});$('#form').oninput=async e=>{if(busy||e.target.type==='file')return;capture();const editing=current;try{await put(editing);if(current!==editing)return;message('Rascunho salvo neste dispositivo.');}catch(e){message('Falha ao salvar: '+e.message,true);}if(e.target.name.startsWith('answer-')){const n=Number(e.target.name.split('-')[1]);$(`[name="note-${n}"]`).required=current.answers[n].value==='Não Aplicável';const details=$(`#notes-${n}`);if(current.answers[n].value!=='Conforme')details.open=true;details.querySelector('.note-required').textContent=current.answers[n].value==='Não Aplicável'?'(obrigatória)':'(opcional)';}};$('#form').onsubmit=save;$('#form').querySelectorAll('[data-photo]').forEach(el=>el.onchange=attach);$('#form').querySelectorAll('[data-remove]').forEach(el=>el.onclick=async()=>{const [n,j]=el.dataset.remove.split(':').map(Number);current.answers[n].photos.splice(j,1);await put(current);render();});}
else{$('#pdf').onclick=downloadPDF;$('#correct').onclick=async()=>{const records=await all();const latest=Math.max(...records.filter(x=>x.id===current.id).map(x=>x.revision));if(current.revision!==latest){message('Abra a revisão mais recente para corrigir.',true);return;}const existing=records.find(x=>x.id===current.id&&x.status==='draft');if(existing){current=existing;}else{current=structuredClone(current);current.revision++;current.key=key(current);current.parentRevision=latest;current.status='draft';current.pdfStatus='pending';current.fields.reason='';current.signature=null;current.workerPhoto=null;delete current.recordedAt;current.updatedAt=stamp();await put(current);}await list();render();};}
const pdfPreparation=!draft?downloadPDF():null;$('#json').onclick=()=>download(JSON.stringify({format:'ppl-local-backup',schema:1,records:[current]},null,2),'application/json',current.key+'.json');return pdfPreparation;}
function setupSignature(){const canvas=$('#signature'),ctx=canvas.getContext('2d');ctx.strokeStyle='#123e55';ctx.lineWidth=3;ctx.lineCap='round';let drawing=false;if(current.signature){const im=new Image();im.onload=()=>ctx.drawImage(im,0,0,900,240);im.src=current.signature.data;}function point(e){const rect=canvas.getBoundingClientRect();return [(e.clientX-rect.left)*900/rect.width,(e.clientY-rect.top)*240/rect.height];}canvas.onpointerdown=e=>{if(busy)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drawing=true;ctx.beginPath();ctx.moveTo(...point(e));};canvas.onpointermove=e=>{if(!drawing)return;e.preventDefault();ctx.lineTo(...point(e));ctx.stroke();};canvas.onpointerup=async e=>{if(!drawing)return;ctx.lineTo(...point(e));ctx.stroke();drawing=false;current.signature={data:canvas.toDataURL('image/png'),createdAt:stamp(),kind:'drawn-electronic'};current.updatedAt=stamp();try{await put(current);message('Assinatura desenhada salva.');}catch(e){message(e.message,true);}};canvas.onpointercancel=canvas.onpointerup;$('#clear-signature').onclick=async()=>{ctx.clearRect(0,0,900,240);current.signature=null;current.updatedAt=stamp();await put(current);};}
function capture(){const f=new FormData($('#form'));for(const k of Object.keys(current.fields))if(f.has(k))current.fields[k]=String(f.get(k)).trim();current.answers.forEach((a,n)=>{a.value=f.get('answer-'+n)||'';a.notes=String(f.get('note-'+n)||'').trim();});current.updatedAt=stamp();const count=current.answers.filter(a=>a.value).length;$('#progress-count').textContent=`${count} de ${current.answers.length} itens respondidos`;$('#progress-bar').value=count;}
async function attach(e){if(busy)return;busy=true;const r=current,n=+e.target.dataset.photo;try{capture();for(const file of e.target.files){if(r.answers[n].photos.length>=3)throw Error('Limite de 3 fotos por item.');if(file.size>15*1024*1024)throw Error('Foto maior que 15 MB.');const data=await resize(file);r.answers[n].photos.push({id:recordUUID(),name:file.name,createdAt:stamp(),data});}await put(r);message('Fotos salvas neste dispositivo.');}catch(e){await put(r);message('Foto: '+e.message,true);}finally{busy=false;render();}}
async function resize(file){const img=await createImageBitmap(file),scale=Math.min(1,1400/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);img.close();return c.toDataURL('image/jpeg',.8);}
async function save(e){e.preventDefault();if(busy)return;capture();if(!$('#form').reportValidity())return;if(['type','date','belt','inspector','employee'].some(k=>!current.fields[k])||(current.revision>1&&!current.fields.reason)){message('Preencha todos os campos obrigatórios, incluindo nome e matrícula.',true);return;}if(current.answers.some(a=>!ANSWERS.includes(a.value)||(a.value==='Não Aplicável'&&!a.notes))){message('Responda todos os itens e justifique Não Aplicável.',true);return;}if(current.fields.date>dateToday()){message('A data não pode ser futura.',true);return;}if(!current.workerPhoto){message('Adicione o registro fotográfico do colaborador antes de salvar.',true);return;}if(!current.signature){message('Assine no espaço ao final antes de registrar.',true);return;}busy=true;try{const stored=await getRecord(current.key);if(stored?.status==='recorded'){current=stored;message('Este registro já foi preservado.');return;}current.status='recorded';current.recordedAt=stamp();current.updatedAt=current.recordedAt;current.pdfStatus='pending';try{await put(current);}catch(e){if(navigator.onLine&&typeof window.PPL_RECEIVE_RECORD==='function'){try{await window.PPL_RECEIVE_RECORD(current);current.syncStatus='central-only';transientRecords.set(current.key,structuredClone(current));}catch(remoteError){current.status='draft';delete current.recordedAt;throw Error('Não foi possível preservar no aparelho nem confirmar no servidor: '+remoteError.message);}}else{current.status='draft';delete current.recordedAt;throw e;}}window.dispatchEvent(new Event('ppl-record-ready'));message(current.syncStatus==='central-only'?'Inspeção recebida pelo servidor. A cópia local não foi confirmada; preparando PDF.':'Inspeção salva neste dispositivo. Preparando a cópia PDF e o envio ao servidor.');}catch(err){message('Dados/PDF: '+err.message+'. Consulte o registro e tente gerar o PDF novamente.',true);}finally{busy=false;try{await list();}catch(e){message('Não foi possível atualizar a lista local: '+e.message,true);}render();}}
function download(data,type,name){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name.replace(/:/g,'-');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
const pdfJobs=new Map(),pdfMemory=new Map();
function cachedPDFBlob(row){return row?.bytes?new Blob([row.bytes],{type:'application/pdf'}):row?.blob;}
async function preparedPDF(r){if(pdfMemory.has(r.key))return new Blob([pdfMemory.get(r.key)],{type:'application/pdf'});try{const cached=cachedPDFBlob(await transaction('pdfs','readonly',s=>s.get(r.key)));if(cached)return cached;}catch{}return new Blob([await generateAndStore(r)],{type:'application/pdf'});}
function generateAndStore(r){if(pdfJobs.has(r.key))return pdfJobs.get(r.key);const snapshot=structuredClone(r);const job=(async()=>{let bytes;try{bytes=await deadline(makePDF(snapshot),60000,'A geração do PDF demorou além do esperado. A inspeção está preservada; tente novamente.');}catch(e){snapshot.pdfStatus='failed';r.pdfStatus='failed';try{await put(snapshot);}catch{}throw e;}pdfMemory.set(r.key,bytes);let durable=false;try{await transaction('pdfs','readwrite',s=>s.put({key:r.key,bytes:bytes.slice().buffer}));durable=true;}catch(e){message('PDF pronto para baixar e enviar. A cópia PDF neste navegador não foi confirmada: '+storageError(e)+'. Mantenha a página aberta até o recebimento central.',true);}if(durable)pdfMemory.delete(r.key);else{while(pdfMemory.size>3)pdfMemory.delete(pdfMemory.keys().next().value);}snapshot.pdfStatus=durable?'ready':'pending';r.pdfStatus=snapshot.pdfStatus;try{await put(snapshot);}catch(e){message('PDF pronto. Não foi possível atualizar sua indicação local: '+storageError(e),true);}window.dispatchEvent(new Event('ppl-record-ready'));return bytes;})().finally(()=>pdfJobs.delete(r.key));pdfJobs.set(r.key,job);return job;}
function storageError(e){return (e?.name&&e.name!=='Error'?e.name+': ':'')+(e?.message||'Falha no armazenamento local.');}
function rememberInspection(r){try{sessionStorage.setItem('ppl-last-inspection',r.key);}catch{}}
async function restoreLastInspection(){let k;try{k=sessionStorage.getItem('ppl-last-inspection');}catch{}if(k){const saved=await getRecord(k);if(saved)current=saved;}}
function localPDFAddress(r,attachment=false){const address=new URL('_pdf/'+encodeURIComponent(r.key)+'.pdf',new URL('./',location.href));if(attachment)address.searchParams.set('download','1');return address.href;}
let activePDF=null;
async function downloadPDF(){if(busy||!current||current.status!=='recorded')return;busy=true;const r=current,host=$('#pdf-output');if(!host){busy=false;return;}host.innerHTML='<p>Preparando relatório PDF...</p>';try{const blob=await preparedPDF(r);if(current!==r||$('#pdf-output')!==host)return;const name=`PPL-${r.id}-r${r.revision}.pdf`;if(activePDF)URL.revokeObjectURL(activePDF.url);const url=URL.createObjectURL(blob),file=typeof File==='function'?new File([blob],name,{type:'application/pdf'}):null;activePDF={key:r.key,url,file};const stable=r.pdfStatus==='ready'&&!!navigator.serviceWorker?.controller,openURL=stable?localPDFAddress(r):url,downloadURL=stable?localPDFAddress(r,true):url;let share=false;try{share=!!file&&!!navigator.share&&!!navigator.canShare?.({files:[file]});}catch{}host.innerHTML=`<div class="pdf-ready"><strong>Relatório PDF pronto</strong><p>${esc(name)}</p><p class="muted">${r.pdfStatus==='ready'?'Cópia PDF preservada neste navegador.':'PDF disponível nesta tela; a cópia local ainda não foi confirmada.'} O recebimento central é confirmado separadamente no aviso de sincronização.</p><div class="actions">${share?'<button type="button" class="primary" id="share-pdf">Salvar PDF no aparelho</button>':''}<a class="pdf-download" href="${downloadURL}" download="${esc(name)}">Baixar arquivo PDF</a><a class="pdf-open" href="${openURL}" target="_blank" rel="noopener">Abrir relatório PDF</a></div><p class="muted">Se o PDF abrir em vez de baixar, use o menu do navegador para salvar o arquivo. O backup JSON fica separado abaixo.</p><details><summary>Onde encontrar o PDF no aparelho?</summary><p><strong>iPhone / iPad:</strong> use Salvar PDF no aparelho → Salvar em Arquivos → No Meu iPhone (ou No Meu iPad) → escolha a pasta → Salvar. Para os downloads do Safari ficarem na memória do iPhone, configure Ajustes → Apps → Safari → Downloads → No Meu iPhone. Depois procure no app Arquivos → Explorar → No Meu iPhone → Downloads.</p><p><strong>Android:</strong> procure no app Arquivos / Meus Arquivos → Downloads, ou na pasta escolhida pelo navegador.</p><p><strong>Computador:</strong> procure em Downloads ou na pasta escolhida ao baixar. O destino é definido pelo navegador e pelo sistema do aparelho.</p></details></div>`;if(share)$('#share-pdf').onclick=async()=>{try{await navigator.share({files:[file],title:'Relatório de inspeção PPL'});}catch(e){if(e.name!=='AbortError')message('Não foi possível abrir o compartilhamento. Use Baixar arquivo PDF ou Abrir relatório PDF.',true);}};}catch(e){if($('#pdf-output')===host)host.innerHTML='<p class="error">Não foi possível preparar o PDF: '+esc(e.message)+'. O registro permanece salvo. Clique em Exportar relatório PDF para tentar novamente.</p>';}finally{busy=false;}}
async function makePDF(r){const {PDFDocument,StandardFonts,rgb}=PDFLib;const doc=await PDFDocument.create(),font=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold);const logo=await doc.embedPng('data:image/png;base64,');let page,y,pageNo=0;const blue=rgb(0,.35,.47);const printable=t=>String(t).replace(/[^\u0020-\u007e\u00a0-\u00ff\n]/g,'?');
function newPage(){page=doc.addPage([595.28,841.89]);pageNo++;y=755;page.drawImage(logo,{x:36,y:788,width:168,height:168*logo.height/logo.width});page.drawText('INSPEÇÕES DIGITAIS · PILOTO LOCAL',{x:225,y:805,size:11,font:bold,color:blue});page.drawText('Registro de inspeção - avaliação técnica pendente',{x:225,y:786,size:8,font});page.drawLine({start:{x:36,y:775},end:{x:559,y:775},color:blue,thickness:2});page.drawText(`ID ${r.id} | r${r.revision} | página ${pageNo}`,{x:36,y:27,size:8,font});page.drawText('Elaborador do aplicativo: Paulo Ricardo Reis',{x:36,y:57,size:8,font});page.drawText('Identificação declarada. Sem assinatura certificada. Não libera equipamento.',{x:36,y:42,size:8,font});}
function line(text,size=10,isBold=false){const ft=isBold?bold:font;const paragraphs=printable(text).split('\n');for(const para of paragraphs){let s='';for(const word of para.split(' ')){if(ft.widthOfTextAtSize(s+' '+word,size)>515&&s){draw(s);s='';}if(ft.widthOfTextAtSize(word,size)>515){for(const char of word){if(ft.widthOfTextAtSize(s+char,size)>515){draw(s);s='';}s+=char;}}else s+=(s?' ':'')+word;}draw(s);}function draw(s){if(y<75)newPage();page.drawText(s,{x:36,y,size,font:ft});y-=size+5;}}
newPage();line(r.model.title,12,true);y-=8;line(`Modelo: ${r.model.id} | versão: ${r.model.version}`,9);line(`Inspeção: ${r.fields.type} | data: ${r.fields.date}`);if(r.model.equipmentMode==='generic'){line(`Equipamento: ${equipmentLabel(r)}`);line(`${r.model.identificationLabel}: ${r.fields.belt}`);for(const f of r.model.identifiers||[])line(`${f.label}: ${r.fields[f.name]||'Não informada'}`);line(`Situação do equipamento: ${r.fields.beltState}`);line(`Origem: ${r.model.source.form} | aba: ${r.model.source.sheet.trim()}`,9);}else{line(`Cinturão / TAG: ${r.fields.belt}`);if(r.model.equipmentMode==='component'){line('Talabarte: componente integrante do conjunto, sem TAG própria.');line(`Avarias adicionais do talabarte: ${r.fields.lanyardDamage||'Nenhuma observação informada'}`);line(`Situação do cinturão: ${r.fields.beltState}`);}else{line(`Identificação histórica do talabarte: ${r.fields.lanyard||'Não informada'}`);line(`Situação do cinturão: ${r.fields.beltState} | talabarte: ${r.fields.lanyardState}`);}}line(`Observação da situação / baixa: ${r.fields.dispositionNotes||'Sem observação'}`);line(`Unidade: ${r.fields.unit||'Não informada'} | equipe: ${r.fields.team||'Não informada'}`);line(`Inspetor / usuário: ${r.fields.inspector} | matrícula: ${r.fields.employee}`);line(`Criado: ${localTime(r.createdAt)} | registrado: ${localTime(r.recordedAt)}`,9);line('Fuso: America/Fortaleza. Horários do dispositivo; sem validação pelo servidor.',9);if(r.parentRevision)line(`Corrige revisão ${r.parentRevision}. Motivo: ${r.fields.reason}`);y-=8;
for(let n=0;n<r.model.items.length;n++){const item=r.model.items[n],a=r.answers[n];if(y<150)newPage();line(r.model.equipmentMode==='generic'?`${n+1}. ${item.category} | item original ${item.sourceNumber}`:`${n+1}. ${item.category} | vínculo proposto: ${item.target}`,11,true);line(item.text);line(`Resposta: ${a.value}`,10,true);line(`Observação: ${a.notes||'Sem observação'}`);if(a.photos.length)line(`Evidências: ${a.photos.length} foto(s) na montagem ao final.`,9);y-=12;}
line('OBSERVAÇÕES GERAIS',11,true);line(r.fields.notes||'Sem observação');line(r.answers.some(a=>a.value==='Não Conforme')?'Há Não Conforme. Tratamento e avaliação técnica pendentes.':'Avaliação técnica pendente.',11,true);if(r.model.source){line('ORIENTAÇÕES DO FORMULÁRIO DE ORIGEM',11,true);for(const t of r.model.source.guidance)line(t,9);}line('Transcrição e vínculos do modelo aguardam validação técnica. O PDF apresenta os dados locais preservados; não comprova autenticidade ou imutabilidade.',9);if(r.signature){if(y<330)newPage();line('IDENTIFICAÇÃO DO RESPONSÁVEL PELA INSPEÇÃO',11,true);const top=y-12,height=210;for(const x of [36,304])page.drawRectangle({x,y:top-height,width:255,height,borderWidth:1,borderColor:rgb(.69,.79,.83),color:rgb(.985,.99,.995)});page.drawText('ASSINATURA ELETRÔNICA DESENHADA',{x:46,y:top-20,size:8,font:bold,color:blue});page.drawText('Sem certificado digital',{x:46,y:top-35,size:8,font});const signature=await doc.embedPng(r.signature.data);page.drawImage(signature,{x:46,y:top-135,width:235,height:235*signature.height/signature.width});page.drawText(fitCaption(localTime(r.signature.createdAt),235,8),{x:46,y:top-195,size:8,font});page.drawText('REGISTRO FOTOGRÁFICO DO COLABORADOR',{x:314,y:top-20,size:8,font:bold,color:blue});if(r.workerPhoto){const photo=await doc.embedJpg(r.workerPhoto.data),sz=photo.scale(Math.min(235/photo.width,148/photo.height));page.drawImage(photo,{x:314+(235-sz.width)/2,y:top-36-148+(148-sz.height)/2,width:sz.width,height:sz.height});page.drawText(fitCaption(localTime(r.workerPhoto.createdAt),235,8),{x:314,y:top-195,size:8,font});}else page.drawText('Foto não exigida na versão original.',{x:314,y:top-85,size:8,font});y=top-height-20;line(`Responsável declarado: ${r.fields.inspector} | matrícula: ${r.fields.employee}`,9);}function fitCaption(t,max,size){t=printable(t);while(font.widthOfTextAtSize(t,size)>max)t=t.slice(0,-4)+'...';return t;}const evidence=r.answers.flatMap((a,n)=>a.photos.map(photo=>({photo,item:r.model.items[n],number:n+1})));
for(let offset=0;offset<evidence.length;offset+=4){newPage();line('EVIDÊNCIAS FOTOGRÁFICAS',13,true);line(`Montagem ${Math.floor(offset/4)+1} de ${Math.ceil(evidence.length/4)} | Até 4 fotos por página`,9);for(let j=0;j<Math.min(4,evidence.length-offset);j++){const e=evidence[offset+j],x=36+(j%2)*268,top=708-Math.floor(j/2)*308,w=255,h=290;page.drawRectangle({x,y:top-h,width:w,height:h,borderWidth:1,borderColor:rgb(.69,.79,.83),color:rgb(.97,.985,.99)});page.drawText(`Foto ${offset+j+1} · Item ${e.number}`,{x:x+10,y:top-20,size:10,font:bold,color:blue});const im=await doc.embedJpg(e.photo.data),sz=im.scale(Math.min(235/im.width,210/im.height));page.drawImage(im,{x:x+10+(235-sz.width)/2,y:top-40-210+(210-sz.height)/2,width:sz.width,height:sz.height});const fit=(t,max,size)=>{t=printable(t);while(font.widthOfTextAtSize(t,size)>max)t=t.slice(0,-4)+'...';return t;};page.drawText(fit(e.item.category,235,9),{x:x+10,y:top-263,size:9,font:bold});page.drawText(fit(e.photo.name,235,8),{x:x+10,y:top-277,size:8,font});}}
doc.setTitle(`PPL ${r.id} r${r.revision}`);doc.setSubject(r.model.version);return doc.save();}
document.addEventListener('click',e=>{if(e.target.closest('#new')&&!busy)newRecord().catch(err=>message(err.message,true));});$('#choose-equipment').onclick=chooseEquipmentHome;
$('#backup').onclick=async()=>download(JSON.stringify({format:'ppl-local-backup',schema:1,exportedAt:stamp(),records:await all(),management:await transaction('management','readonly',s=>s.getAll())},null,2),'application/json','ppl-backup.json');
function validImport(r){const known=knownSnapshot(r?.model);if(!r||typeof r.id!=='string'||!/^[a-f0-9-]{36}$/.test(r.id)||!Number.isInteger(r.revision)||r.revision<1||r.key!==key(r)||!['draft','recorded'].includes(r.status)||!known||JSON.stringify(r.model)!==JSON.stringify(known)&&!(r.model.id===MODEL.id&&JSON.stringify(r.model.items)===JSON.stringify(known.items)&&JSON.stringify(r.model.types)===JSON.stringify(known.types)))return false;
if(r.status==='recorded'&&r.model.version!=='0.1-transcricao-pendente'&&(!r.signature||r.signature.kind!=='drawn-electronic'||!/^data:image\/png;base64,[a-zA-Z0-9+/=]+$/.test(r.signature.data)))return false;
if(r.workerPhoto&&!validWorkerPhoto(r.workerPhoto))return false;if(r.status==='recorded'&&(known.requiresWorkerPhoto||r.model.version==='0.5-piloto')&&!validWorkerPhoto(r.workerPhoto))return false;
const optional=['unit','team','lanyardDamage',...(r.model.version==='0.1-transcricao-pendente'?['beltState','lanyardState','dispositionNotes']:[])];if(!r.fields||Object.keys(fresh().fields).filter(k=>!optional.includes(k)).some(k=>typeof r.fields[k]!=='string')||Object.entries(r.fields).some(([k,v])=>typeof v!=='string')||(known.identifiers||[]).some(f=>typeof r.fields[f.name]!=='string')||!Array.isArray(r.answers)||r.answers.length!==known.items.length)return false;
return r.answers.every((a,n)=>a.itemId===known.items[n].id&&typeof a.notes==='string'&&(a.value===''&&r.status==='draft'||ANSWERS.includes(a.value))&&Array.isArray(a.photos)&&a.photos.length<=3&&a.photos.every(p=>typeof p.name==='string'&&typeof p.data==='string'&&/^data:image\/jpeg;base64,[a-zA-Z0-9+/=]+$/.test(p.data)))&&['createdAt','updatedAt',...(r.status==='recorded'?['recordedAt']:[])].every(k=>!isNaN(Date.parse(r[k])));}
$('#restore').onchange=async e=>{if(busy)return;busy=true;try{const file=e.target.files[0];if(!file)return;if(file.size>100*1024*1024)throw Error('Backup maior que 100 MB.');const data=JSON.parse(await file.text());if(data.format!=='ppl-local-backup'||data.schema!==1||!Array.isArray(data.records)||!data.records.every(validImport))throw Error('Backup inválido ou versão de modelo incompatível.');for(const name of ['management'])if(data[name]!==undefined&&(!Array.isArray(data[name])||!data[name].every(row=>validManagementBackup(name,row))))throw Error('Dados de gestão inválidos no backup');let added=0,skipped=0;for(const r of data.records){const existing=await transaction('records','readonly',s=>s.get(r.key));if(existing){skipped++;continue;}r.pdfStatus='pending';r.syncStatus='local-only';await put(r);added++;}for(const name of ['management'])if(Array.isArray(data[name]))for(const row of data[name]){if(!validManagementBackup(name,row))throw Error('Dados de gestão inválidos no backup');const old=await transaction(name,'readonly',s=>s.get(row.key));if(!old)await transaction(name,'readwrite',s=>s.put(row));}await list();message(`${added} registros restaurados; ${skipped} IDs existentes preservados. PDFs podem ser gerados novamente.`);}catch(e){message('Restauração: '+e.message,true);}finally{busy=false;$('#restore').value='';}};
function connection(){$('#connection').textContent=navigator.onLine?'Local · conexão disponível':'Local · sem internet';}addEventListener('online',connection);addEventListener('offline',connection);connection();
async function offlineReady(){if(!('serviceWorker'in navigator)){$('#offline-ready').textContent='Teste pela rede Wi-Fi: mantenha o computador ligado. Offline no celular requer HTTPS.';return;}try{await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(resolve=>navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true}));$('#offline-ready').textContent='Pronto para uso offline neste navegador · versão 30.';}catch(e){$('#offline-ready').textContent='Cache offline indisponível. Mantenha esta página aberta e faça backup dos registros.';}}
async function init(){await openLocalDB();await list();await restoreLastInspection();render();offlineReady();if(['management','owner'].includes(new URLSearchParams(location.search).get('access')))setTimeout(()=>$('#management-nav').click(),0);}init().catch(e=>message('Armazenamento indisponível: '+e.message,true));



function validWorkerPhoto(p){return !!p&&typeof p.name==='string'&&typeof p.data==='string'&&/^data:image\/jpeg;base64,[a-zA-Z0-9+/=]+$/.test(p.data)&&!isNaN(Date.parse(p.createdAt));}
async function attachWorkerPhoto(e){if(busy||!e.target.files.length)return;busy=true;const r=current;try{capture();const file=e.target.files[0];if(file.size>15*1024*1024)throw Error('Foto maior que 15 MB.');const data=await resize(file);r.workerPhoto={id:recordUUID(),name:file.name,createdAt:stamp(),data};r.updatedAt=stamp();await put(r);message('Registro fotográfico do colaborador salvo neste dispositivo.');}catch(err){message('Foto do colaborador: '+err.message,true);}finally{busy=false;render();$('#worker-photo-input')?.scrollIntoView({block:'center'});}}

